// Вопросы и развёрнутые ответы из двух опросов. Первый вариант в choices верный.
window.questionBank = [
  {"survey":1,"number":1,"topic":"Динамические системы и моделирование","prompt":"Что такое динамическая система? Чем она отличается от статической?","answer":"<p>Динамическая система имеет состояние, которое меняется во времени по заданному закону. Её выход может зависеть от накопленного состояния и текущего входа. В статической модели выход определяется текущим входом: <img class=\"formula-image\" src=\"./formulas/a002460ff2e3537b.png\" alt=\"y=f(u)\" style=\"width:4.067em;vertical-align:-0.333em\">. Например, температура в комнате зависит от начальной температуры и от того, сколько времени работал обогреватель.</p>","choices":["Состояние динамической системы развивается во времени, а в статической модели выход определяется текущим входом.","Динамическая система определяет выход только текущим входом, а статическая хранит историю.","Различие в том, что динамическая система имеет несколько входов, а статическая — ровно один."]},
  {"survey":1,"number":2,"topic":"Динамические системы и моделирование","prompt":"Что такое состояние системы?","answer":"<p>Состояние <img class=\"formula-image\" src=\"./formulas/bd17c3345d8ec87a.png\" alt=\"x\" style=\"width:0.783em;vertical-align:-0.125em\"> — набор величин, достаточный, чтобы по модели и заданным будущим входам определить дальнейшее поведение системы. Для груза на пружине состояние можно описать положением и скоростью.</p>","choices":["Состояние — набор величин, достаточный вместе с моделью и будущими входами для определения дальнейшего поведения.","Состояние — текущий выход системы при любых обстоятельствах.","Состояние — набор только внешних воздействий, приложенных в данный момент."]},
  {"survey":1,"number":3,"topic":"Динамические системы и моделирование","prompt":"Что такое входные (управляющие) и выходные переменные системы?","answer":"<p>Входные переменные описывают внешние воздействия на систему. Управляющий вход <img class=\"formula-image\" src=\"./formulas/bb064dfcf89d48e7.png\" alt=\"u\" style=\"width:0.824em;vertical-align:-0.125em\"> задают целенаправленно, чтобы повлиять на её поведение. Выходные переменные <img class=\"formula-image\" src=\"./formulas/1858f5f977721c78.png\" alt=\"y\" style=\"width:0.810em;vertical-align:-0.333em\"> — величины, которые измеряют или рассчитывают как результат работы системы. Например, у системы отопления управляющий вход — мощность нагревателя, выход — температура в комнате.</p>","choices":["Входы задают внешние воздействия, а выходы — измеряемые или вычисляемые результаты работы системы.","Входы представляют измеренные результаты, а выходы задают внешние воздействия.","Входы и выходы — постоянные коэффициенты, описывающие внутреннее устройство системы."]},
  {"survey":1,"number":4,"topic":"Динамические системы и моделирование","prompt":"Что такое математическая модель? Какова её цель?","answer":"<p>Математическая модель — описание существенных для задачи свойств объекта или процесса с помощью математических средств, например уравнений или вероятностных зависимостей. Она позволяет объяснять поведение системы, прогнозировать его и проверять последствия изменения входов или параметров.</p>","choices":["Математическая модель описывает существенные свойства объекта и позволяет исследовать и прогнозировать его поведение.","Математическая модель — список измерений, который не содержит связи между величинами.","Математическая модель должна воспроизводить абсолютно все свойства объекта независимо от цели."]},
  {"survey":1,"number":5,"topic":"Динамические системы и моделирование","prompt":"Что такое «чёрный ящик» в контексте моделирования систем?","answer":"<p>Это представление системы через связь входов и выходов без явного описания её внутреннего устройства. Эту связь можно оценить по наблюдениям: подать известные входы и измерить выходы.</p>","choices":["У чёрного ящика описывают связь входов с выходами без явной модели внутреннего устройства.","У чёрного ящика описывают только внутреннее устройство, исключая измерение выходов.","Чёрный ящик — любая система, выход которой всегда равен нулю."]},
  {"survey":1,"number":6,"topic":"Динамические системы и моделирование","prompt":"Чем детерминированные модели отличаются от стохастических?","answer":"<p>Детерминированная модель при одинаковых начальных условиях, параметрах и входах даёт одну и ту же траекторию. Стохастическая модель содержит случайные величины или процессы, поэтому при повторении условий возможны разные траектории. Например, в модель движения можно добавить случайные порывы ветра.</p>","choices":["При одинаковых начальных условиях и входах детерминированная модель даёт ту же траекторию, а стохастическая может давать разные.","При одинаковых условиях стохастическая модель всегда повторяет траекторию, а детерминированная может менять её случайно.","Детерминированность определяется тем, задано ли время непрерывно."]},
  {"survey":1,"number":7,"topic":"Динамические системы и моделирование","prompt":"Что такое модель «в непрерывном времени» и «в дискретном времени»? Приведите примеры их представления.","answer":"<p>В непрерывном времени состояние <img class=\"formula-image\" src=\"./formulas/e4fc9d0e496bc65b.png\" alt=\"x(t)\" style=\"width:2.008em;vertical-align:-0.333em\"> определено для каждого <img class=\"formula-image\" src=\"./formulas/9c1d2a3a6024e581.png\" alt=\"t\" style=\"width:0.645em;vertical-align:-0.125em\"> на интервале. Например, <img class=\"formula-image\" src=\"./formulas/ce2f95a66dacf006.png\" alt=\"\\dot{x}(t)=-2x(t)+u(t)\" style=\"width:9.804em;vertical-align:-0.333em\"> — дифференциальное уравнение. В дискретном времени состояние <img class=\"formula-image\" src=\"./formulas/6f5de028e4cf9b60.png\" alt=\"x_k\" style=\"width:1.240em;vertical-align:-0.329em\"> задано на отдельных шагах <img class=\"formula-image\" src=\"./formulas/7cef662c3e948812.png\" alt=\"k\" style=\"width:0.802em;vertical-align:-0.125em\"> (например, в моменты <img class=\"formula-image\" src=\"./formulas/53895dca24ed50f8.png\" alt=\"t_k=k\\Delta t\" style=\"width:3.947em;vertical-align:-0.329em\">). Пример разностного уравнения: <img class=\"formula-image\" src=\"./formulas/2a106a250489cdad.png\" alt=\"x_{k+1}=0{,}8x_k+u_k\" style=\"width:8.360em;vertical-align:-0.329em\">.</p>","choices":["В непрерывном времени состояние задано на интервале, например дифференциальным уравнением, а в дискретном — на шагах, например разностным уравнением.","В непрерывном времени состояние задают только на целых шагах, а в дискретном — для каждого момента интервала.","Непрерывность времени означает, что состояние обязательно может принимать лишь целочисленные значения."]},
  {"survey":1,"number":8,"topic":"Векторы","prompt":"Что такое вектор? Чем он отличается от скаляра? Как обозначаются векторы на письме и как они изображаются геометрически?","answer":"<p>В евклидовой геометрии ненулевой вектор имеет длину и направление, а скаляр — это число. Векторы обозначают стрелкой над буквой (<img class=\"formula-image\" src=\"./formulas/2f1c9c00f219b567.png\" alt=\"\\vec a\" style=\"width:0.807em;vertical-align:-0.125em\">) или полужирной буквой (<img class=\"formula-image\" src=\"./formulas/01780c1dc6532765.png\" alt=\"\\mathbf a\" style=\"width:0.807em;vertical-align:-0.125em\">). Геометрически ненулевой вектор изображают направленным отрезком.</p>","choices":["Ненулевой вектор имеет длину и направление и изображается стрелкой. Скаляр — число.","И вектор, и скаляр всегда имеют направление, но только скаляр имеет координаты.","Вектор — одно число без направления, которое на рисунке представлено точкой."]},
  {"survey":1,"number":9,"topic":"Векторы","prompt":"Что такое модуль (длина) вектора? Как он обозначается?","answer":"<p>Модуль вектора — его длина, обозначаемая <img class=\"formula-image\" src=\"./formulas/cf837293ff983e0f.png\" alt=\"|\\vec a|\" style=\"width:1.393em;vertical-align:-0.208em\"> или <img class=\"formula-image\" src=\"./formulas/f08b67f1eb018a6a.png\" alt=\"\\|\\vec a\\|\" style=\"width:1.736em;vertical-align:-0.250em\">. В ортонормированном базисе для <img class=\"formula-image\" src=\"./formulas/cd0f663d094caf38.png\" alt=\"\\vec a=(a_1,\\ldots,a_n)\" style=\"width:7.020em;vertical-align:-0.333em\"> модуль равен <img class=\"formula-image\" src=\"./formulas/b2d55fbba0828a74.png\" alt=\"\\sqrt{a_1^2+\\cdots+a_n^2}\" style=\"width:6.842em;vertical-align:-1.315em\">.</p>","choices":["Модуль — длина вектора <img class=\"formula-image\" src=\"./formulas/f08b67f1eb018a6a.png\" alt=\"\\|\\vec a\\|\" style=\"width:1.736em;vertical-align:-0.250em\">, равная квадратному корню из суммы квадратов координат в ортонормированном базисе.","Модуль — сумма координат вектора со знаками.","Модуль — направление вектора, определённое углом к оси."]},
  {"survey":1,"number":10,"topic":"Векторы","prompt":"Что такое нулевой вектор? Чему равен его модуль?","answer":"<p>Нулевой вектор <img class=\"formula-image\" src=\"./formulas/b3659683dcd5fed8.png\" alt=\"\\vec 0\" style=\"width:0.804em;vertical-align:-0.125em\"> имеет нулевые координаты. Его модуль равен нулю, направление не определено.</p>","choices":["У нулевого вектора все координаты нулевые, и его модуль равен нулю.","Нулевой вектор имеет единичный модуль и нулевое направление.","Нулевой вектор — любой вектор, у которого хотя бы одна координата равна нулю."]},
  {"survey":1,"number":11,"topic":"Векторы","prompt":"Какие векторы называются коллинеарными? Приведите пример.","answer":"<p>Два ненулевых вектора коллинеарны, если лежат на одной прямой или на параллельных прямых. Тогда <img class=\"formula-image\" src=\"./formulas/0d23799797b54eb8.png\" alt=\"\\vec b=\\lambda\\vec a\" style=\"width:3.166em;vertical-align:-0.125em\">. Например, <img class=\"formula-image\" src=\"./formulas/9491ffac273a5f2d.png\" alt=\"(3,6)=3(1,2)\" style=\"width:6.727em;vertical-align:-0.333em\">. Нулевой вектор считают коллинеарным любому вектору.</p>","choices":["Ненулевые векторы коллинеарны, если один кратен другому, например <img class=\"formula-image\" src=\"./formulas/cd868252bf0655c3.png\" alt=\"(1,2)\" style=\"width:2.561em;vertical-align:-0.333em\"> и <img class=\"formula-image\" src=\"./formulas/c3601c6fadc5adc6.png\" alt=\"(3,6)\" style=\"width:2.561em;vertical-align:-0.333em\">.","Ненулевые векторы коллинеарны, если они перпендикулярны, например <img class=\"formula-image\" src=\"./formulas/3e84b7a368618c99.png\" alt=\"(1,0)\" style=\"width:2.561em;vertical-align:-0.333em\"> и <img class=\"formula-image\" src=\"./formulas/ee28a18e90a054a9.png\" alt=\"(0,1)\" style=\"width:2.561em;vertical-align:-0.333em\">.","Коллинеарны любые векторы одинаковой длины, например <img class=\"formula-image\" src=\"./formulas/cd868252bf0655c3.png\" alt=\"(1,2)\" style=\"width:2.561em;vertical-align:-0.333em\"> и <img class=\"formula-image\" src=\"./formulas/e85fd8b5e17475ac.png\" alt=\"(2,1)\" style=\"width:2.561em;vertical-align:-0.333em\">."]},
  {"survey":1,"number":12,"topic":"Векторы","prompt":"Какие векторы называются компланарными?","answer":"<p>Векторы компланарны, если после переноса к общему началу они лежат в одной плоскости. В <img class=\"formula-image\" src=\"./formulas/57dc135daadb5254.png\" alt=\"\\mathbb R^3\" style=\"width:1.345em;vertical-align:-0.125em\"> три вектора компланарны тогда и только тогда, когда их смешанное произведение <img class=\"formula-image\" src=\"./formulas/3bb30cab836c2a79.png\" alt=\"\\vec a\\cdot(\\vec b\\times\\vec c)\" style=\"width:4.301em;vertical-align:-0.333em\"> равно нулю.</p>","choices":["Векторы компланарны, если их можно перенести к общему началу и уложить в одну плоскость.","Векторы компланарны, если никакие два из них не лежат в общей плоскости.","Компланарность требует, чтобы все векторы имели равные координаты."]},
  {"survey":1,"number":13,"topic":"Скалярное произведение","prompt":"Что такое скалярное произведение двух векторов? Дайте алгебраическое и геометрическое определение.","answer":"<p>Скалярное произведение даёт число. Алгебраически в ортонормированном базисе это сумма произведений соответствующих координат: <img class=\"formula-image\" src=\"./formulas/8d1db19c647c210b.png\" alt=\"\\vec a\\cdot\\vec b=\\sum_{i=1}^n a_i b_i\" style=\"width:7.651em;vertical-align:-0.490em\">. Геометрически для ненулевых векторов <img class=\"formula-image\" src=\"./formulas/5eaa6b9ecd676fa9.png\" alt=\"\\vec a\\cdot\\vec b=\\|\\vec a\\|\\|\\vec b\\|\\cos\\varphi\" style=\"width:8.297em;vertical-align:-0.333em\">, где <img class=\"formula-image\" src=\"./formulas/a8bfabfece8d2886.png\" alt=\"\\varphi\" style=\"width:0.928em;vertical-align:-0.333em\"> — угол между ними. Если один из векторов нулевой, произведение равно нулю.</p>","choices":["Скалярное произведение равно сумме произведений координат в ортонормированном базисе и равно <img class=\"formula-image\" src=\"./formulas/e6e77dce1eec16b9.png\" alt=\"\\|\\vec a\\|\\|\\vec b\\|\\cos\\varphi\" style=\"width:5.283em;vertical-align:-0.333em\"> для ненулевых векторов.","Скалярное произведение двух ненулевых векторов равно <img class=\"formula-image\" src=\"./formulas/458cae0d115d03f8.png\" alt=\"\\|\\vec a\\|\\|\\vec b\\|\\sin\\varphi\" style=\"width:5.146em;vertical-align:-0.333em\">.","Скалярное произведение возвращает вектор, перпендикулярный обоим множителям."]},
  {"survey":1,"number":14,"topic":"Скалярное произведение","prompt":"Как вычислить скалярное произведение через координаты векторов?","answer":"<p>В ортонормированном базисе перемножить попарно соответствующие координаты и сложить результаты. Например, <img class=\"formula-image\" src=\"./formulas/d00c2b9c0d29f765.png\" alt=\"(1,2,3)\\cdot(4,0,-1)=1\\cdot4+2\\cdot0+3\\cdot(-1)=1\" style=\"width:21.265em;vertical-align:-0.333em\">.</p>","choices":["Попарно перемножают соответствующие координаты и складывают произведения.","Сначала складывают координаты каждого вектора, затем перемножают две суммы.","Складывают квадраты попарных разностей координат."]},
  {"survey":1,"number":15,"topic":"Скалярное произведение","prompt":"Как найти угол между двумя векторами, используя скалярное произведение?","answer":"<p>Для ненулевых векторов <img class=\"formula-image\" src=\"./formulas/754e93009349a90f.png\" alt=\"\\varphi=\\arccos\\left(\\dfrac{\\vec a\\cdot\\vec b}{\\|\\vec a\\|\\|\\vec b\\|}\\right)\" style=\"width:9.512em;vertical-align:-1.319em\">, где <img class=\"formula-image\" src=\"./formulas/65b804de332117c7.png\" alt=\"0\\leq\\varphi\\leq\\pi\" style=\"width:4.683em;vertical-align:-0.333em\">.</p>","choices":["Для ненулевых векторов угол равен <img class=\"formula-image\" src=\"./formulas/99af477ded9a7e8e.png\" alt=\"\\arccos\\left(\\frac{\\vec a\\cdot\\vec b}{\\|\\vec a\\|\\|\\vec b\\|}\\right)\" style=\"width:6.745em;vertical-align:-1.111em\">.","Для ненулевых векторов угол равен <img class=\"formula-image\" src=\"./formulas/b053098804f0fb1c.png\" alt=\"\\arcsin\\left(\\frac{\\vec a\\cdot\\vec b}{\\|\\vec a\\|\\|\\vec b\\|}\\right)\" style=\"width:6.609em;vertical-align:-1.111em\">.","Для ненулевых векторов угол равен <img class=\"formula-image\" src=\"./formulas/501f45c907d92d39.png\" alt=\"\\arccos\\left((\\vec a\\cdot\\vec b)\\|\\vec a\\|\\|\\vec b\\|\\right)\" style=\"width:9.992em;vertical-align:-0.673em\">."]},
  {"survey":1,"number":16,"topic":"Скалярное произведение","prompt":"Что означает, если скалярное произведение двух ненулевых векторов равно нулю?","answer":"<p>Векторы ортогональны. Угол между ними равен <img class=\"formula-image\" src=\"./formulas/8f5ff6a2bccb9b13.png\" alt=\"90^\\circ\" style=\"width:1.732em;vertical-align:-0.125em\">.</p>","choices":["Два ненулевых вектора ортогональны, и угол между ними <img class=\"formula-image\" src=\"./formulas/8f5ff6a2bccb9b13.png\" alt=\"90^\\circ\" style=\"width:1.732em;vertical-align:-0.125em\">.","Два ненулевых вектора коллинеарны, и угол между ними <img class=\"formula-image\" src=\"./formulas/0a5c146a58ad1309.png\" alt=\"0^\\circ\" style=\"width:1.178em;vertical-align:-0.125em\"> или <img class=\"formula-image\" src=\"./formulas/7f459b9cc11ae74e.png\" alt=\"180^\\circ\" style=\"width:2.286em;vertical-align:-0.125em\">.","Два ненулевых вектора обязательно имеют одинаковые модули."]},
  {"survey":1,"number":17,"topic":"Скалярное произведение","prompt":"Чему равно скалярное произведение ортов <img class=\"formula-image\" src=\"./formulas/3ff4a23831f052c8.png\" alt=\"\\mathbf i\\cdot\\mathbf i\" style=\"width:1.500em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/acb0edc57ff9c434.png\" alt=\"\\mathbf j\\cdot\\mathbf j\" style=\"width:1.585em;vertical-align:-0.333em\">, <img class=\"formula-image\" src=\"./formulas/bf308730886b6531.png\" alt=\"\\mathbf i\\cdot\\mathbf j\" style=\"width:1.542em;vertical-align:-0.333em\">?","answer":"<p><img class=\"formula-image\" src=\"./formulas/5bf131da57f63c9c.png\" alt=\"\\mathbf i\\cdot\\mathbf i=1\" style=\"width:3.356em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/6c13663a1a04b2ed.png\" alt=\"\\mathbf j\\cdot\\mathbf j=1\" style=\"width:3.441em;vertical-align:-0.333em\">, <img class=\"formula-image\" src=\"./formulas/a105404ed5c64546.png\" alt=\"\\mathbf i\\cdot\\mathbf j=0\" style=\"width:3.398em;vertical-align:-0.333em\">. Орты координатных осей имеют единичную длину и взаимно перпендикулярны.</p>","choices":["По порядку: 1, 1, 0.","По порядку: 0, 0, 1.","По порядку: 1, 1, 1."]},
  {"survey":1,"number":18,"topic":"Векторное произведение","prompt":"Что такое векторное произведение двух векторов? Каков его результат (скаляр или вектор)?","answer":"<p>Векторное произведение <img class=\"formula-image\" src=\"./formulas/19742cf0ab351a82.png\" alt=\"\\vec a\\times\\vec b\" style=\"width:2.395em;vertical-align:-0.125em\"> в трёхмерном пространстве даёт вектор. Для неколлинеарных множителей он перпендикулярен обоим, а его направление определяется правилом правой руки. Для коллинеарных множителей результат — нулевой вектор.</p>","choices":["В трёхмерном пространстве результат — вектор, перпендикулярный обоим множителям, если они неколлинеарны.","Результат всегда скаляр, равный произведению длин на косинус угла.","Результат всегда лежит в плоскости множителей и направлен вдоль их суммы."]},
  {"survey":1,"number":19,"topic":"Векторное произведение","prompt":"Как направлен вектор-результат векторного произведения? Сформулируйте правило правой руки.","answer":"<p>Для <img class=\"formula-image\" src=\"./formulas/19742cf0ab351a82.png\" alt=\"\\vec a\\times\\vec b\" style=\"width:2.395em;vertical-align:-0.125em\"> согните пальцы правой руки от первого вектора <img class=\"formula-image\" src=\"./formulas/2f1c9c00f219b567.png\" alt=\"\\vec a\" style=\"width:0.807em;vertical-align:-0.125em\"> ко второму <img class=\"formula-image\" src=\"./formulas/77abbbdaee3fba77.png\" alt=\"\\vec b\" style=\"width:0.789em;vertical-align:-0.125em\"> через меньший угол между ними. Отставленный большой палец покажет направление произведения, перпендикулярное плоскости этих векторов. Перестановка множителей меняет направление на противоположное.</p>","choices":["Пальцы правой руки сгибают от первого вектора ко второму, а большой палец указывает направление ненулевого произведения.","Пальцы правой руки сгибают от второго вектора к первому, а большой палец указывает направление ненулевого произведения.","Результат направлен вдоль первого вектора независимо от направления второго."]},
  {"survey":1,"number":20,"topic":"Векторное произведение","prompt":"Чему равен модуль векторного произведения? Какой геометрический смысл он имеет (площадь параллелограмма)?","answer":"<p>Для ненулевых векторов <img class=\"formula-image\" src=\"./formulas/e198d10535cbbb68.png\" alt=\"\\|\\vec a\\times\\vec b\\|=\\|\\vec a\\|\\|\\vec b\\|\\sin\\varphi\" style=\"width:9.521em;vertical-align:-0.333em\">. Это площадь параллелограмма, построенного на этих векторах. При нулевом множителе площадь и модуль равны нулю.</p>","choices":["Модуль равен <img class=\"formula-image\" src=\"./formulas/458cae0d115d03f8.png\" alt=\"\\|\\vec a\\|\\|\\vec b\\|\\sin\\varphi\" style=\"width:5.146em;vertical-align:-0.333em\"> и выражает площадь параллелограмма.","Модуль равен <img class=\"formula-image\" src=\"./formulas/e6e77dce1eec16b9.png\" alt=\"\\|\\vec a\\|\\|\\vec b\\|\\cos\\varphi\" style=\"width:5.283em;vertical-align:-0.333em\"> и выражает площадь параллелограмма.","Модуль равен <img class=\"formula-image\" src=\"./formulas/32268203e9b60224.png\" alt=\"\\frac12\\|\\vec a\\|\\|\\vec b\\|\\sin\\varphi\" style=\"width:5.646em;vertical-align:-0.628em\"> и выражает площадь параллелограмма."]},
  {"survey":1,"number":21,"topic":"Векторное произведение","prompt":"Как вычислить векторное произведение через координаты векторов (с помощью определителя матрицы)?","answer":"<p>В правом ортонормированном базисе записывают формальный определитель и раскладывают его по первой строке:</p><div class=\"formula\"><img class=\"formula-image\" src=\"./formulas/2bfec50b1d6e247c.png\" alt=\"\\vec a\\times\\vec b= \\begin{vmatrix} \\mathbf i &amp; \\mathbf j &amp; \\mathbf k\\\\ a_x &amp; a_y &amp; a_z\\\\ b_x &amp; b_y &amp; b_z \\end{vmatrix} =(a_y b_z-a_z b_y)\\mathbf i +(a_z b_x-a_x b_z)\\mathbf j +(a_x b_y-a_y b_x)\\mathbf k.\" style=\"width:33.882em;vertical-align:-0.000em\"></div>","choices":["В первую строку формального определителя ставят орты, ниже — координаты множителей по порядку, затем раскладывают по первой строке.","В первой строке записывают орты, а обе следующие строки заполняют координатами первого множителя.","Вычисляют определитель из двух строк координат и возвращают скаляр даже для трёхмерных векторов."]},
  {"survey":1,"number":22,"topic":"Векторное произведение","prompt":"Что означает, если векторное произведение двух ненулевых векторов равно нулевому вектору?","answer":"<p>Векторы коллинеарны: они сонаправлены или противоположно направлены. Угол между ними равен <img class=\"formula-image\" src=\"./formulas/0a5c146a58ad1309.png\" alt=\"0^\\circ\" style=\"width:1.178em;vertical-align:-0.125em\"> или <img class=\"formula-image\" src=\"./formulas/7f459b9cc11ae74e.png\" alt=\"180^\\circ\" style=\"width:2.286em;vertical-align:-0.125em\">.</p>","choices":["Два ненулевых вектора коллинеарны.","Два ненулевых вектора перпендикулярны.","Два ненулевых вектора обязательно имеют равные модули."]},
  {"survey":1,"number":23,"topic":"Векторное произведение","prompt":"Чему равно векторное произведение ортов <img class=\"formula-image\" src=\"./formulas/8b2a13d2c7d2cb6e.png\" alt=\"\\mathbf i\\times\\mathbf i\" style=\"width:1.932em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/071c468cd61b08b6.png\" alt=\"\\mathbf i\\times\\mathbf j\" style=\"width:1.975em;vertical-align:-0.333em\">, <img class=\"formula-image\" src=\"./formulas/f238ac0a90f12732.png\" alt=\"\\mathbf j\\times\\mathbf i\" style=\"width:1.975em;vertical-align:-0.333em\">?","answer":"<p>В правом ортонормированном базисе <img class=\"formula-image\" src=\"./formulas/74b11078c9be10f0.png\" alt=\"\\mathbf i\\times\\mathbf i=\\vec 0\" style=\"width:3.788em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/983f9e207734c44a.png\" alt=\"\\mathbf i\\times\\mathbf j=\\mathbf k\" style=\"width:3.829em;vertical-align:-0.333em\">, <img class=\"formula-image\" src=\"./formulas/e8116941b8c6c2f6.png\" alt=\"\\mathbf j\\times\\mathbf i=-\\mathbf k\" style=\"width:5.020em;vertical-align:-0.333em\">.</p>","choices":["По порядку: нулевой вектор, <img class=\"formula-image\" src=\"./formulas/6b7b87acbd89095d.png\" alt=\"\\mathbf k\" style=\"width:0.802em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/d7462980ed3c0f0f.png\" alt=\"-\\mathbf k\" style=\"width:1.549em;vertical-align:-0.125em\">.","По порядку: <img class=\"formula-image\" src=\"./formulas/8dc1e3da793e0861.png\" alt=\"\\mathbf i\" style=\"width:0.567em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/6b7b87acbd89095d.png\" alt=\"\\mathbf k\" style=\"width:0.802em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/6b7b87acbd89095d.png\" alt=\"\\mathbf k\" style=\"width:0.802em;vertical-align:-0.125em\">.","По порядку: нулевой вектор, <img class=\"formula-image\" src=\"./formulas/d7462980ed3c0f0f.png\" alt=\"-\\mathbf k\" style=\"width:1.549em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/6b7b87acbd89095d.png\" alt=\"\\mathbf k\" style=\"width:0.802em;vertical-align:-0.125em\">."]},
  {"survey":1,"number":24,"topic":"Матрицы и определители","prompt":"Что такое матрица? Что такое элементы матрицы?","answer":"<p>Матрица — прямоугольная таблица элементов из <img class=\"formula-image\" src=\"./formulas/0b09bab4ecd9f7f8.png\" alt=\"m\" style=\"width:1.089em;vertical-align:-0.125em\"> строк и <img class=\"formula-image\" src=\"./formulas/50e51d8d432b2520.png\" alt=\"n\" style=\"width:0.824em;vertical-align:-0.125em\"> столбцов. Элемент <img class=\"formula-image\" src=\"./formulas/448c15a02939f598.png\" alt=\"a_{ij}\" style=\"width:1.348em;vertical-align:-0.495em\"> — число (или иной объект), стоящее в строке <img class=\"formula-image\" src=\"./formulas/1355b588042018b3.png\" alt=\"i\" style=\"width:0.567em;vertical-align:-0.125em\"> и столбце <img class=\"formula-image\" src=\"./formulas/1839fcf1636a011e.png\" alt=\"j\" style=\"width:0.609em;vertical-align:-0.333em\">.</p>","choices":["Матрица — прямоугольная таблица, а её элемент задаётся номером строки и столбца.","Матрица — упорядоченный набор единственного столбца, независимо от её размера.","Матрица — только квадратная таблица, элемент которой задаётся лишь номером строки."]},
  {"survey":1,"number":25,"topic":"Матрицы и определители","prompt":"Что такое главная и побочная диагонали матрицы?","answer":"<p>У квадратной матрицы <img class=\"formula-image\" src=\"./formulas/ecacde06412fa61f.png\" alt=\"n\\times n\" style=\"width:2.447em;vertical-align:-0.125em\"> главная диагональ идёт из левого верхнего угла в правый нижний и состоит из элементов <img class=\"formula-image\" src=\"./formulas/c5ad23b46fc1e502.png\" alt=\"a_{ii}\" style=\"width:1.348em;vertical-align:-0.329em\">. Побочная диагональ идёт из правого верхнего угла в левый нижний и состоит из элементов <img class=\"formula-image\" src=\"./formulas/47cd972fe92ad25e.png\" alt=\"a_{i,n+1-i}\" style=\"width:4.223em;vertical-align:-0.412em\">.</p>","choices":["Главная идёт сверху слева вниз направо, побочная в квадратной матрице — сверху справа вниз налево.","Главная идёт сверху справа вниз налево, побочная — сверху слева вниз направо.","Главная состоит из первой строки, побочная — из последнего столбца."]},
  {"survey":1,"number":26,"topic":"Матрицы и определители","prompt":"Какая матрица называется нулевой? Единичной?","answer":"<p>У нулевой матрицы все элементы равны нулю. Единичная матрица <img class=\"formula-image\" src=\"./formulas/881c3be07047f600.png\" alt=\"I_n\" style=\"width:1.087em;vertical-align:-0.329em\"> — квадратная матрица с единицами на главной диагонали и нулями на остальных позициях.</p>","choices":["У нулевой все элементы равны нулю, у единичной единицы на главной диагонали и нули на остальных позициях.","У нулевой нули только на главной диагонали, у единичной все элементы равны единице.","У нулевой нули только вне диагонали, у единичной единицы на побочной диагонали."]},
  {"survey":1,"number":27,"topic":"Матрицы и определители","prompt":"Как выполняется сложение и вычитание матриц?","answer":"<p>Матрицы одинакового размера складывают и вычитают поэлементно: <img class=\"formula-image\" src=\"./formulas/0be0c710a8dbadca.png\" alt=\"(A\\pm B)_{ij}=a_{ij}\\pm b_{ij}\" style=\"width:8.775em;vertical-align:-0.656em\">.</p>","choices":["Матрицы одинакового размера складывают и вычитают поэлементно.","При сложении сравнивают только число строк и достраивают недостающие столбцы нулями.","В каждой позиции складывают целую строку первой матрицы и столбец второй."]},
  {"survey":1,"number":28,"topic":"Матрицы и определители","prompt":"Как умножить матрицу на число?","answer":"<p>Умножить каждый элемент матрицы на это число: <img class=\"formula-image\" src=\"./formulas/e50aebce3d404c7d.png\" alt=\"(\\lambda A)_{ij}=\\lambda a_{ij}\" style=\"width:5.691em;vertical-align:-0.656em\">.</p>","choices":["Каждый элемент матрицы умножают на это число.","На число умножают только элементы главной диагонали.","На число умножают только первый столбец матрицы."]},
  {"survey":1,"number":29,"topic":"Матрицы и определители","prompt":"Как выполняется умножение матриц? Почему это не коммутативная операция?","answer":"<p>Если <img class=\"formula-image\" src=\"./formulas/5726c5629058340d.png\" alt=\"A\" style=\"width:0.883em;vertical-align:-0.125em\"> имеет размер <img class=\"formula-image\" src=\"./formulas/7b6a6e982c33864e.png\" alt=\"m\\times n\" style=\"width:2.711em;vertical-align:-0.125em\">, а <img class=\"formula-image\" src=\"./formulas/019f8a5633773c8d.png\" alt=\"B\" style=\"width:0.906em;vertical-align:-0.125em\"> — <img class=\"formula-image\" src=\"./formulas/2888c8a80a6365fa.png\" alt=\"n\\times p\" style=\"width:2.430em;vertical-align:-0.333em\">, то <img class=\"formula-image\" src=\"./formulas/7f9dcdc81e0409ea.png\" alt=\"AB\" style=\"width:1.540em;vertical-align:-0.125em\"> имеет размер <img class=\"formula-image\" src=\"./formulas/fcdd6ff1c4786f4c.png\" alt=\"m\\times p\" style=\"width:2.695em;vertical-align:-0.333em\">. Его элемент <img class=\"formula-image\" src=\"./formulas/792a133195c3adb1.png\" alt=\"c_{ij}=\\sum_{k=1}^n a_{ik}b_{kj}\" style=\"width:7.940em;vertical-align:-0.495em\"> получается умножением строки <img class=\"formula-image\" src=\"./formulas/1355b588042018b3.png\" alt=\"i\" style=\"width:0.567em;vertical-align:-0.125em\"> первой матрицы на столбец <img class=\"formula-image\" src=\"./formulas/1839fcf1636a011e.png\" alt=\"j\" style=\"width:0.609em;vertical-align:-0.333em\"> второй. Порядок важен: при перестановке меняются строки и столбцы, участвующие в вычислении. Например,</p><div class=\"formula\"><img class=\"formula-image\" src=\"./formulas/3ce1f8c36c26a506.png\" alt=\"A=\\begin{pmatrix}1&amp;0\\\\0&amp;0\\end{pmatrix},\\qquad B=\\begin{pmatrix}0&amp;1\\\\0&amp;0\\end{pmatrix} \\quad\\Longrightarrow\\quad AB=B,\\qquad BA=0_{2\\times2}.\" style=\"width:29.331em;vertical-align:-0.000em\"></div><p>Для некоторых размеров обратный порядок умножения вообще не определён.</p>","choices":["Берут скалярное произведение строки первой матрицы и столбца второй, и перестановка множителей в общем случае меняет результат.","При умножении перемножают только соответствующие элементы, поэтому порядок матриц всегда безразличен.","При умножении берут две строки с одинаковыми номерами, поэтому порядок множителей не влияет на результат."]},
  {"survey":1,"number":30,"topic":"Матрицы и определители","prompt":"Что такое определитель матрицы? Для каких матриц он существует?","answer":"<p>Определитель <img class=\"formula-image\" src=\"./formulas/e6785d58d43c33dd.png\" alt=\"\\det A\" style=\"width:2.264em;vertical-align:-0.125em\"> — число, вычисляемое по элементам квадратной матрицы. Его модуль показывает, во сколько раз соответствующее линейное преобразование изменяет площадь в двумерном случае или объём в трёхмерном. Квадратная матрица обратима тогда и только тогда, когда её определитель отличен от нуля.</p>","choices":["Это число, определённое для квадратных матриц. Ненулевое значение означает обратимость.","Это вектор из сумм по столбцам, определённый для любой матрицы.","Это число, определённое только для квадратных матриц с ненулевой диагональю."]},
  {"survey":1,"number":31,"topic":"Матрицы и определители","prompt":"Как вычислить определитель матрицы <img class=\"formula-image\" src=\"./formulas/1de06e2aa756152f.png\" alt=\"2\\times2\" style=\"width:2.406em;vertical-align:-0.125em\">, <img class=\"formula-image\" src=\"./formulas/129d5f0f9350e4a1.png\" alt=\"3\\times3\" style=\"width:2.406em;vertical-align:-0.125em\">?","answer":"<p>Для <img class=\"formula-image\" src=\"./formulas/1de06e2aa756152f.png\" alt=\"2\\times2\" style=\"width:2.406em;vertical-align:-0.125em\"> вычесть произведение элементов побочной диагонали из произведения элементов главной: <img class=\"formula-image\" src=\"./formulas/e0c6c73ed37265cf.png\" alt=\"\\begin{vmatrix}a&amp;b\\\\c&amp;d\\end{vmatrix}=ad-bc\" style=\"width:9.312em;vertical-align:-1.014em\">.</p><p>Для <img class=\"formula-image\" src=\"./formulas/129d5f0f9350e4a1.png\" alt=\"3\\times3\" style=\"width:2.406em;vertical-align:-0.125em\"> можно разложить определитель по первой строке с чередующимися знаками <img class=\"formula-image\" src=\"./formulas/d6218ad1916d799a.png\" alt=\"+,-,+\" style=\"width:4.124em;vertical-align:-0.250em\">:</p><div class=\"formula\"><img class=\"formula-image\" src=\"./formulas/f2f775c1aca36661.png\" alt=\"\\begin{vmatrix} a &amp; b &amp; c\\\\ d &amp; e &amp; f\\\\ g &amp; h &amp; i \\end{vmatrix} =a(ei-fh)-b(di-fg)+c(dh-eg).\" style=\"width:23.794em;vertical-align:-0.000em\"></div>","choices":["Для <img class=\"formula-image\" src=\"./formulas/757bd14767290a1a.png\" alt=\"2\\times 2\" style=\"width:2.406em;vertical-align:-0.125em\"> используют <img class=\"formula-image\" src=\"./formulas/9f5a1cb601057074.png\" alt=\"ad-bc\" style=\"width:3.578em;vertical-align:-0.125em\">, а для <img class=\"formula-image\" src=\"./formulas/19a8d2491525f75e.png\" alt=\"3\\times 3\" style=\"width:2.406em;vertical-align:-0.125em\"> можно разложить по первой строке со знаками <img class=\"formula-image\" src=\"./formulas/d6218ad1916d799a.png\" alt=\"+,-,+\" style=\"width:4.124em;vertical-align:-0.250em\">.","Для <img class=\"formula-image\" src=\"./formulas/757bd14767290a1a.png\" alt=\"2\\times 2\" style=\"width:2.406em;vertical-align:-0.125em\"> используют <img class=\"formula-image\" src=\"./formulas/139e80e139090ce0.png\" alt=\"ad+bc\" style=\"width:3.578em;vertical-align:-0.167em\">, а для <img class=\"formula-image\" src=\"./formulas/19a8d2491525f75e.png\" alt=\"3\\times 3\" style=\"width:2.406em;vertical-align:-0.125em\"> в разложении берут только знаки +.","Для <img class=\"formula-image\" src=\"./formulas/757bd14767290a1a.png\" alt=\"2\\times 2\" style=\"width:2.406em;vertical-align:-0.125em\"> складывают элементы главной диагонали, а для <img class=\"formula-image\" src=\"./formulas/19a8d2491525f75e.png\" alt=\"3\\times 3\" style=\"width:2.406em;vertical-align:-0.125em\"> перемножают их."]},
  {"survey":2,"number":1,"topic":"Гармонический осциллятор","prompt":"Что такое простейшая колебательная система (гармонический осциллятор)? Что такое гармонические колебания?","answer":"<p>Идеальный гармонический осциллятор — система, в которой возвращающая сила пропорциональна отклонению от положения равновесия и направлена к нему. Пример — груз на пружине без трения и внешнего воздействия. Гармонические колебания описываются синусоидой <img class=\"formula-image\" src=\"./formulas/e83605bf9c0569d2.png\" alt=\"x(t)=A\\cos(\\omega_0t+\\varphi)\" style=\"width:9.623em;vertical-align:-0.333em\">, где <img class=\"formula-image\" src=\"./formulas/5726c5629058340d.png\" alt=\"A\" style=\"width:0.883em;vertical-align:-0.125em\"> — амплитуда, <img class=\"formula-image\" src=\"./formulas/aa464f17f0cd5fb5.png\" alt=\"\\omega_0\" style=\"width:1.434em;vertical-align:-0.329em\"> — угловая частота, <img class=\"formula-image\" src=\"./formulas/a8bfabfece8d2886.png\" alt=\"\\varphi\" style=\"width:0.928em;vertical-align:-0.333em\"> — начальная фаза.</p>","choices":["Возвращающая сила пропорциональна отклонению и направлена к равновесию, поэтому свободное движение идеальной системы синусоидально.","Возвращающая сила постоянна по модулю, поэтому координата идеального осциллятора всегда меняется по синусоиде.","Сила направлена от равновесия, поэтому отклонение периодически меняет знак."]},
  {"survey":2,"number":2,"topic":"Гармонический осциллятор","prompt":"Какое дифференциальное уравнение описывает простейшую колебательную систему?","answer":"<p>Для груза массы <img class=\"formula-image\" src=\"./formulas/0b09bab4ecd9f7f8.png\" alt=\"m\" style=\"width:1.089em;vertical-align:-0.125em\"> на пружине жёсткости <img class=\"formula-image\" src=\"./formulas/7cef662c3e948812.png\" alt=\"k\" style=\"width:0.802em;vertical-align:-0.125em\"> второй закон Ньютона даёт <img class=\"formula-image\" src=\"./formulas/51bb2bd1e542c7d3.png\" alt=\"m\\ddot x=-kx\" style=\"width:5.199em;vertical-align:-0.125em\">. Отсюда <img class=\"formula-image\" src=\"./formulas/aecca2193c21a1dd.png\" alt=\"\\ddot x+\\omega_0^2x=0\" style=\"width:5.546em;vertical-align:-0.398em\">, где <img class=\"formula-image\" src=\"./formulas/3769748cc461f53d.png\" alt=\"\\omega_0=\\sqrt{k/m}\" style=\"width:5.384em;vertical-align:-0.521em\">. Здесь <img class=\"formula-image\" src=\"./formulas/bd17c3345d8ec87a.png\" alt=\"x\" style=\"width:0.783em;vertical-align:-0.125em\"> — отклонение от равновесия, а <img class=\"formula-image\" src=\"./formulas/aaf83f87b18a6401.png\" alt=\"\\ddot x\" style=\"width:0.783em;vertical-align:-0.125em\"> — ускорение.</p>","choices":["<img class=\"formula-image\" src=\"./formulas/139ad7c030e1408e.png\" alt=\"x''+\\omega_0^2x=0\" style=\"width:6.004em;vertical-align:-0.398em\">.","<img class=\"formula-image\" src=\"./formulas/2fc32bc5d9c2e2c1.png\" alt=\"x''-\\omega_0^2x=0\" style=\"width:6.004em;vertical-align:-0.398em\">.","<img class=\"formula-image\" src=\"./formulas/8ab698af8106022b.png\" alt=\"x'+\\omega_0^2x=0\" style=\"width:5.796em;vertical-align:-0.398em\">."]},
  {"survey":2,"number":3,"topic":"Гармонический осциллятор","prompt":"Что такое характеристическое уравнение?","answer":"<p>Для линейного однородного дифференциального уравнения с постоянными коэффициентами характеристическое уравнение получают подстановкой <img class=\"formula-image\" src=\"./formulas/04e7f15d92125855.png\" alt=\"x=e^{\\lambda t}\" style=\"width:3.288em;vertical-align:-0.125em\"> и делением на <img class=\"formula-image\" src=\"./formulas/b97d3c85004a5b64.png\" alt=\"e^{\\lambda t}\" style=\"width:1.454em;vertical-align:-0.125em\">. Для гармонического осциллятора это <img class=\"formula-image\" src=\"./formulas/b53ed25912658d5c.png\" alt=\"\\lambda^2+\\omega_0^2=0\" style=\"width:5.456em;vertical-align:-0.398em\">. Корни определяют вид решений.</p>","choices":["Это уравнение для <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\">, которое у линейного однородного ОДУ с постоянными коэффициентами получают подстановкой <img class=\"formula-image\" src=\"./formulas/04e7f15d92125855.png\" alt=\"x=e^{\\lambda t}\" style=\"width:3.288em;vertical-align:-0.125em\">.","Это исходное дифференциальное уравнение после подстановки начального значения <img class=\"formula-image\" src=\"./formulas/1cab4beb345cd75f.png\" alt=\"x(0)\" style=\"width:2.167em;vertical-align:-0.333em\">.","Это уравнение, которое задаёт только амплитуду и не связано с видом решения."]},
  {"survey":2,"number":4,"topic":"Гармонический осциллятор","prompt":"Что означает комплексность корней характеристического уравнения?","answer":"<p>У уравнения с вещественными коэффициентами пара корней <img class=\"formula-image\" src=\"./formulas/1034bf6fd4228e18.png\" alt=\"\\alpha\\pm i\\beta\" style=\"width:2.964em;vertical-align:-0.333em\">, где <img class=\"formula-image\" src=\"./formulas/3b684200798e4fb2.png\" alt=\"\\beta\\ne0\" style=\"width:2.712em;vertical-align:-0.333em\">, даёт колебательную составляющую <img class=\"formula-image\" src=\"./formulas/fb7d3adbf6ba2589.png\" alt=\"e^{\\alpha t}(C_1\\cos\\beta t+C_2\\sin\\beta t)\" style=\"width:10.337em;vertical-align:-0.333em\">. Мнимая часть задаёт угловую частоту <img class=\"formula-image\" src=\"./formulas/67b5ba74d1e955fd.png\" alt=\"|\\beta|\" style=\"width:1.442em;vertical-align:-0.333em\">. При <img class=\"formula-image\" src=\"./formulas/ca4d29d2140e051f.png\" alt=\"\\alpha&lt;0\" style=\"width:2.708em;vertical-align:-0.125em\"> амплитуда затухает, при <img class=\"formula-image\" src=\"./formulas/5637297ea6953e79.png\" alt=\"\\alpha&gt;0\" style=\"width:2.708em;vertical-align:-0.125em\"> растёт, при <img class=\"formula-image\" src=\"./formulas/095a7792d0a829cd.png\" alt=\"\\alpha=0\" style=\"width:2.706em;vertical-align:-0.125em\"> постоянна. У идеального осциллятора корни <img class=\"formula-image\" src=\"./formulas/81067c156d18b30f.png\" alt=\"\\pm i\\omega_0\" style=\"width:2.498em;vertical-align:-0.329em\">.</p>","choices":["Пара комплексно-сопряжённых корней даёт колебательную составляющую. Действительная часть задаёт затухание или рост.","Пара комплексных корней всегда даёт чистое затухание без колебаний.","Комплексность корней означает, что действительные решения не существуют."]},
  {"survey":2,"number":5,"topic":"Собственные значения и векторы","prompt":"Что такое собственный вектор матрицы <img class=\"formula-image\" src=\"./formulas/5726c5629058340d.png\" alt=\"A\" style=\"width:0.883em;vertical-align:-0.125em\">? Что такое собственное значение?","answer":"<p>Собственный вектор квадратной матрицы <img class=\"formula-image\" src=\"./formulas/5726c5629058340d.png\" alt=\"A\" style=\"width:0.883em;vertical-align:-0.125em\"> — ненулевой вектор <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\">, для которого <img class=\"formula-image\" src=\"./formulas/db0a6d6e4eebc9da.png\" alt=\"Av=\\lambda v\" style=\"width:3.792em;vertical-align:-0.125em\">. Число <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> — соответствующее собственное значение.</p>","choices":["Это ненулевой вектор <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\">, для которого <img class=\"formula-image\" src=\"./formulas/db0a6d6e4eebc9da.png\" alt=\"Av=\\lambda v\" style=\"width:3.792em;vertical-align:-0.125em\">, а <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> — соответствующее собственное значение.","Это любой вектор <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\">, для которого <img class=\"formula-image\" src=\"./formulas/1b8f07d0687ce325.png\" alt=\"Av=v\" style=\"width:3.274em;vertical-align:-0.125em\">, а собственное значение всегда равно единице.","Это вектор <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\">, ортогональный <img class=\"formula-image\" src=\"./formulas/66542f51f77c94f3.png\" alt=\"Av\" style=\"width:1.428em;vertical-align:-0.125em\">, а <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> — угол между <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\"> и <img class=\"formula-image\" src=\"./formulas/66542f51f77c94f3.png\" alt=\"Av\" style=\"width:1.428em;vertical-align:-0.125em\">."]},
  {"survey":2,"number":6,"topic":"Собственные значения и векторы","prompt":"Почему собственный вектор должен быть ненулевым?","answer":"<p>Для нулевого вектора равенство <img class=\"formula-image\" src=\"./formulas/fdad538714b919e4.png\" alt=\"A0=\\lambda0\" style=\"width:3.811em;vertical-align:-0.125em\"> выполняется при любом <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\">. Условие <img class=\"formula-image\" src=\"./formulas/6cb87141e45ad238.png\" alt=\"v\\ne0\" style=\"width:2.650em;vertical-align:-0.125em\"> выделяет направление преобразования и позволяет определить соответствующее ему собственное значение.</p>","choices":["Для нулевого вектора <img class=\"formula-image\" src=\"./formulas/db0a6d6e4eebc9da.png\" alt=\"Av=\\lambda v\" style=\"width:3.792em;vertical-align:-0.125em\"> выполняется при любом <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> и потому не определяет соответствующее значение.","Нулевой вектор исключают, потому что равенство <img class=\"formula-image\" src=\"./formulas/db0a6d6e4eebc9da.png\" alt=\"Av=\\lambda v\" style=\"width:3.792em;vertical-align:-0.125em\"> для него никогда не выполняется.","Нулевой вектор допустим, если <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> также равна нулю."]},
  {"survey":2,"number":7,"topic":"Собственные значения и векторы","prompt":"Что означает равенство <img class=\"formula-image\" src=\"./formulas/db0a6d6e4eebc9da.png\" alt=\"Av=\\lambda v\" style=\"width:3.792em;vertical-align:-0.125em\"> геометрически?","answer":"<p>Для вещественных <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\"> и <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> прямая, натянутая на <img class=\"formula-image\" src=\"./formulas/77e760ba12297281.png\" alt=\"v\" style=\"width:0.794em;vertical-align:-0.125em\">, сохраняется в том смысле, что все её точки переходят на эту же прямую. Длина вектора умножается на <img class=\"formula-image\" src=\"./formulas/073879f335b013ac.png\" alt=\"|\\lambda|\" style=\"width:1.354em;vertical-align:-0.208em\">. При <img class=\"formula-image\" src=\"./formulas/3ba4e8eb5553e93d.png\" alt=\"\\lambda&gt;0\" style=\"width:2.626em;vertical-align:-0.125em\"> направление сохраняется, при <img class=\"formula-image\" src=\"./formulas/f13ee7320c8e56df.png\" alt=\"\\lambda&lt;0\" style=\"width:2.626em;vertical-align:-0.125em\"> меняется на противоположное, при <img class=\"formula-image\" src=\"./formulas/88a7b670b81cd1ac.png\" alt=\"\\lambda=0\" style=\"width:2.624em;vertical-align:-0.125em\"> вектор переходит в нулевой.</p>","choices":["Преобразование умножает длину на <img class=\"formula-image\" src=\"./formulas/073879f335b013ac.png\" alt=\"|\\lambda|\" style=\"width:1.354em;vertical-align:-0.208em\"> и оставляет образ на той же прямой. При <img class=\"formula-image\" src=\"./formulas/f13ee7320c8e56df.png\" alt=\"\\lambda&lt;0\" style=\"width:2.626em;vertical-align:-0.125em\"> направление меняется на противоположное.","Преобразование поворачивает вектор на угол <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> и всегда сохраняет его длину.","Преобразование переносит вектор в перпендикулярное направление и сохраняет его длину."]},
  {"survey":2,"number":8,"topic":"Собственные значения и векторы","prompt":"Может ли собственный вектор быть умножен на число?","answer":"<p>Да. При <img class=\"formula-image\" src=\"./formulas/267364bad275cae0.png\" alt=\"c\\ne0\" style=\"width:2.566em;vertical-align:-0.125em\"> вектор <img class=\"formula-image\" src=\"./formulas/38293a67dba72569.png\" alt=\"cv\" style=\"width:1.255em;vertical-align:-0.125em\"> остаётся собственным для того же <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\">, так как <img class=\"formula-image\" src=\"./formulas/cf1271e8bf714862.png\" alt=\"A(cv)=cAv=\\lambda(cv)\" style=\"width:9.314em;vertical-align:-0.333em\">. Умножение на ноль даёт нулевой вектор.</p>","choices":["Любое ненулевое кратное остаётся собственным вектором с тем же собственным значением.","При умножении вектора на <img class=\"formula-image\" src=\"./formulas/a0aedd07c35f310f.png\" alt=\"c\" style=\"width:0.710em;vertical-align:-0.125em\"> его собственное значение тоже умножается на <img class=\"formula-image\" src=\"./formulas/a0aedd07c35f310f.png\" alt=\"c\" style=\"width:0.710em;vertical-align:-0.125em\">.","Масштабировать собственный вектор можно только множителем 1."]},
  {"survey":2,"number":9,"topic":"Собственные значения и векторы","prompt":"Как найти собственные векторы?","answer":"<p>Сначала находят собственные значения из <img class=\"formula-image\" src=\"./formulas/18dd73d8cf67c011.png\" alt=\"\\det(A-\\lambda I)=0\" style=\"width:7.039em;vertical-align:-0.333em\">. Затем для каждого <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> решают однородную систему <img class=\"formula-image\" src=\"./formulas/b571c78b2c2a423c.png\" alt=\"(A-\\lambda I)v=0\" style=\"width:6.202em;vertical-align:-0.333em\">. Её ненулевые решения — собственные векторы для данного <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\">.</p>","choices":["Находят <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> из <img class=\"formula-image\" src=\"./formulas/18dd73d8cf67c011.png\" alt=\"\\det(A-\\lambda I)=0\" style=\"width:7.039em;vertical-align:-0.333em\"> и ненулевые решения <img class=\"formula-image\" src=\"./formulas/b571c78b2c2a423c.png\" alt=\"(A-\\lambda I)v=0\" style=\"width:6.202em;vertical-align:-0.333em\">.","Складывают диагональные элементы <img class=\"formula-image\" src=\"./formulas/5726c5629058340d.png\" alt=\"A\" style=\"width:0.883em;vertical-align:-0.125em\"> и подставляют сумму в качестве единственного <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\">.","Решают <img class=\"formula-image\" src=\"./formulas/e9176e45d8fb0510.png\" alt=\"Av=0\" style=\"width:3.284em;vertical-align:-0.125em\"> для всех <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\"> независимо от значения <img class=\"formula-image\" src=\"./formulas/f67f03c496355976.png\" alt=\"\\lambda\" style=\"width:0.768em;vertical-align:-0.125em\">."]},
  {"survey":2,"number":10,"topic":"Собственные значения и векторы","prompt":"Зачем нужны собственные векторы?","answer":"<p>Они задают направления, вдоль которых линейное преобразование действует умножением на число. В системе <img class=\"formula-image\" src=\"./formulas/48aaae811e591788.png\" alt=\"\\dot x=Ax\" style=\"width:3.251em;vertical-align:-0.125em\"> начальное состояние <img class=\"formula-image\" src=\"./formulas/b922f6e0acdc88ee.png\" alt=\"x(0)=v\" style=\"width:4.014em;vertical-align:-0.333em\"> даёт решение <img class=\"formula-image\" src=\"./formulas/4146a2d1b1c0de73.png\" alt=\"x(t)=e^{\\lambda t}v\" style=\"width:5.058em;vertical-align:-0.333em\">. Если собственные векторы образуют базис, переход к нему разбивает систему на независимые скалярные уравнения.</p>","choices":["Они задают направления простого масштабирования. Базис из них помогает разделить линейную систему на независимые уравнения.","Они нужны, чтобы заменить любую квадратную матрицу единичной без изменения координат.","Они определяют только число строк матрицы и не связаны с динамикой."]},
  {"survey":2,"number":11,"topic":"Численное решение дифференциальных уравнений","prompt":"Что такое метод Эйлера? Какая геометрическая идея лежит в основе метода?","answer":"<p>Явный метод Эйлера приближённо решает задачу <img class=\"formula-image\" src=\"./formulas/df3bd52eb169a49e.png\" alt=\"y'=f(t,y)\" style=\"width:5.068em;vertical-align:-0.333em\"> шагами <img class=\"formula-image\" src=\"./formulas/86c806507900ceac.png\" alt=\"t_{n+1}=t_n+h\" style=\"width:6.294em;vertical-align:-0.329em\">, <img class=\"formula-image\" src=\"./formulas/2e5f559ca83d935a.png\" alt=\"y_{n+1}=y_n+h f(t_n,y_n)\" style=\"width:10.247em;vertical-align:-0.490em\">. На каждом шаге решение заменяют отрезком касательной, построенной по наклону в начале шага. Глобальная погрешность имеет порядок <img class=\"formula-image\" src=\"./formulas/a2cce58593cbb818.png\" alt=\"O(h)\" style=\"width:2.312em;vertical-align:-0.333em\"> при достаточной гладкости решения и правой части.</p>","choices":["Явный шаг идёт по касательной с наклоном в начале шага: <img class=\"formula-image\" src=\"./formulas/2e5f559ca83d935a.png\" alt=\"y_{n+1}=y_n+h f(t_n,y_n)\" style=\"width:10.247em;vertical-align:-0.490em\">.","Явный метод Эйлера использует среднее двух наклонов на каждом шаге и имеет второй порядок.","Явный метод Эйлера заменяет кривую отрезком с наклоном, вычисленным только в неизвестной конечной точке."]},
  {"survey":2,"number":12,"topic":"Численное решение дифференциальных уравнений","prompt":"Что такое улучшенный метод Эйлера? Чем отличается от простого метода Эйлера?","answer":"<p>В варианте Хойна сначала вычисляют наклон <img class=\"formula-image\" src=\"./formulas/ca705fb2431882f0.png\" alt=\"k_1=f(t_n,y_n)\" style=\"width:6.184em;vertical-align:-0.490em\"> и прогноз <img class=\"formula-image\" src=\"./formulas/ad72406ac2668bfa.png\" alt=\"\\tilde y=y_n+hk_1\" style=\"width:6.038em;vertical-align:-0.490em\">. Затем вычисляют <img class=\"formula-image\" src=\"./formulas/699608c7542b975d.png\" alt=\"k_2=f(t_n+h,\\tilde y)\" style=\"width:7.625em;vertical-align:-0.333em\"> и берут шаг по среднему наклону: <img class=\"formula-image\" src=\"./formulas/89ca53a42bd1a047.png\" alt=\"y_{n+1}=y_n+\\tfrac h2(k_1+k_2)\" style=\"width:10.612em;vertical-align:-0.628em\">. Два вычисления правой части на шаг дают второй порядок точности вместо первого. Под улучшенным методом Эйлера также встречается метод средней точки: <img class=\"formula-image\" src=\"./formulas/3f9afa0d810b5605.png\" alt=\"k_2=f(t_n+h/2,y_n+hk_1/2)\" style=\"width:12.775em;vertical-align:-0.490em\"> и <img class=\"formula-image\" src=\"./formulas/d46295c9c14bf018.png\" alt=\"y_{n+1}=y_n+hk_2\" style=\"width:7.635em;vertical-align:-0.490em\">.</p>","choices":["Используют два вычисления правой части и получают второй порядок, например усредняют наклоны начала и прогнозируемого конца шага.","Используют только начальный наклон, а второй порядок получают за счёт увеличения шага.","Используют четыре наклона с весами <img class=\"formula-image\" src=\"./formulas/a4c9c33c6ba77418.png\" alt=\"1:2:2:1\" style=\"width:3.757em;vertical-align:-0.125em\"> на каждом шаге."]},
  {"survey":2,"number":13,"topic":"Численное решение дифференциальных уравнений","prompt":"Что такое метод Рунге-Кутты (4-го порядка)? Сколько вычислений на одном шаге?","answer":"<p>Классический RK4 делает четыре вычисления правой части <img class=\"formula-image\" src=\"./formulas/c929f0631aff2b0f.png\" alt=\"f\" style=\"width:0.800em;vertical-align:-0.125em\"> на шаг: в начале, дважды в середине с разными приближениями <img class=\"formula-image\" src=\"./formulas/1858f5f977721c78.png\" alt=\"y\" style=\"width:0.810em;vertical-align:-0.333em\">, и в конце. Их взвешивают в пропорции <img class=\"formula-image\" src=\"./formulas/a4c9c33c6ba77418.png\" alt=\"1:2:2:1\" style=\"width:3.757em;vertical-align:-0.125em\">.</p><div class=\"formula\"><img class=\"formula-image\" src=\"./formulas/b684680dffbc4af6.png\" alt=\"\\begin{aligned} k_1 &amp;= f(t_n,y_n),\\\\ k_2 &amp;= f(t_n+h/2,y_n+hk_1/2),\\\\ k_3 &amp;= f(t_n+h/2,y_n+hk_2/2),\\\\ k_4 &amp;= f(t_n+h,y_n+hk_3),\\\\ y_{n+1} &amp;= y_n+\\tfrac h6(k_1+2k_2+2k_3+k_4). \\end{aligned}\" style=\"width:17.926em;vertical-align:-0.000em\"></div><p>При достаточной гладкости глобальная погрешность имеет порядок <img class=\"formula-image\" src=\"./formulas/7822420765711639.png\" alt=\"O(h^4)\" style=\"width:2.770em;vertical-align:-0.333em\">.</p>","choices":["Классический RK4 вычисляет правую часть четыре раза на шаг и комбинирует наклоны с весами <img class=\"formula-image\" src=\"./formulas/a4c9c33c6ba77418.png\" alt=\"1:2:2:1\" style=\"width:3.757em;vertical-align:-0.125em\">.","Классический RK4 вычисляет правую часть дважды на шаг и усредняет наклоны.","Классический RK4 вычисляет правую часть один раз за четыре шага."]},
  {"survey":2,"number":14,"topic":"Анализ данных и систем","prompt":"Что такое регрессия?","answer":"<p>Регрессия моделирует зависимость количественной величины <img class=\"formula-image\" src=\"./formulas/1858f5f977721c78.png\" alt=\"y\" style=\"width:0.810em;vertical-align:-0.333em\"> от одной или нескольких объясняющих переменных. Например, в линейной регрессии <img class=\"formula-image\" src=\"./formulas/9352a2ab8531800a.png\" alt=\"\\hat y=a+bx\" style=\"width:4.932em;vertical-align:-0.333em\"> коэффициенты можно подобрать методом наименьших квадратов, минимизируя сумму квадратов отклонений наблюдаемых значений от прогнозов.</p>","choices":["Регрессия моделирует зависимость количественной величины от одной или нескольких объясняющих переменных.","Регрессия — способ случайной перестановки наблюдений для увеличения выборки.","Регрессия — вычисление только коэффициента корреляции без модели зависимости."]},
  {"survey":2,"number":15,"topic":"Анализ данных и систем","prompt":"Что такое прямое и обратное преобразование Фурье?","answer":"<p>Прямое преобразование переводит сигнал <img class=\"formula-image\" src=\"./formulas/e4fc9d0e496bc65b.png\" alt=\"x(t)\" style=\"width:2.008em;vertical-align:-0.333em\"> в частотное представление <img class=\"formula-image\" src=\"./formulas/1929800e89c0ee6b.png\" alt=\"X(\\omega)\" style=\"width:2.452em;vertical-align:-0.333em\">. Обратное восстанавливает сигнал по этому представлению. При использовании угловой частоты <img class=\"formula-image\" src=\"./formulas/f4b832feda2ad098.png\" alt=\"\\omega\" style=\"width:0.976em;vertical-align:-0.125em\"> одна из стандартных пар формул имеет вид</p><div class=\"formula\"><img class=\"formula-image\" src=\"./formulas/1b6cb54a45c19237.png\" alt=\"X(\\omega)=\\int_{-\\infty}^{\\infty}x(t)e^{-i\\omega t}\\,dt,\\qquad x(t)=\\frac{1}{2\\pi}\\int_{-\\infty}^{\\infty}X(\\omega)e^{i\\omega t}\\,d\\omega.\" style=\"width:25.673em;vertical-align:-0.000em\"></div>","choices":["Прямое преобразование получает спектр сигнала, обратное восстанавливает сигнал по спектру.","Прямое преобразование восстанавливает временной сигнал из спектра, обратное строит спектр.","Оба преобразования вычисляют только среднее значение сигнала."]},
  {"survey":2,"number":16,"topic":"Анализ данных и систем","prompt":"Что такое передаточная функция?","answer":"<p>Для линейной стационарной системы с одним входом и одним выходом передаточная функция <img class=\"formula-image\" src=\"./formulas/8ae12dedea59cd28.png\" alt=\"H(s)\" style=\"width:2.271em;vertical-align:-0.333em\"> связывает преобразования Лапласа входа <img class=\"formula-image\" src=\"./formulas/a394d84b8711d150.png\" alt=\"U(s)\" style=\"width:2.232em;vertical-align:-0.333em\"> и выхода <img class=\"formula-image\" src=\"./formulas/bb8c8d8da8a508e5.png\" alt=\"Y(s)\" style=\"width:2.146em;vertical-align:-0.333em\"> при нулевых начальных условиях. Тогда <img class=\"formula-image\" src=\"./formulas/9cce6beff29c6e50.png\" alt=\"Y(s)=H(s)U(s)\" style=\"width:7.452em;vertical-align:-0.333em\">, то есть <img class=\"formula-image\" src=\"./formulas/f445505e6e0b2de8.png\" alt=\"H(s)=Y(s)/U(s)\" style=\"width:7.942em;vertical-align:-0.333em\"> там, где <img class=\"formula-image\" src=\"./formulas/1211d7d312cef7bc.png\" alt=\"U(s)\\ne0\" style=\"width:4.089em;vertical-align:-0.333em\">. Например, для <img class=\"formula-image\" src=\"./formulas/8ed94d8c8f5d316a.png\" alt=\"\\dot y+ay=bu\" style=\"width:5.534em;vertical-align:-0.333em\"> получаем <img class=\"formula-image\" src=\"./formulas/764284597fde0fd6.png\" alt=\"H(s)=b/(s+a)\" style=\"width:7.645em;vertical-align:-0.333em\">.</p>","choices":["Для линейной стационарной системы отношение преобразования Лапласа выхода к преобразованию входа берут при нулевых начальных условиях.","Передаточная функция — отношение начального значения входа к конечному значению выхода.","Передаточная функция — сумма преобразований Лапласа входа и выхода."]},
  {"survey":2,"number":17,"topic":"Анализ данных и систем","prompt":"Что такое корреляция? Отрицательная и положительная корреляция.","answer":"<p>Коэффициент корреляции Пирсона измеряет силу и знак линейной связи двух величин и лежит в диапазоне от <img class=\"formula-image\" src=\"./formulas/3380c951c6fd0f6c.png\" alt=\"-1\" style=\"width:1.551em;vertical-align:-0.125em\"> до <img class=\"formula-image\" src=\"./formulas/1f7a49960033094e.png\" alt=\"1\" style=\"width:0.804em;vertical-align:-0.125em\">. При положительной корреляции большим значениям одной величины обычно соответствуют большие значения другой. При отрицательной — меньшие. Нулевая корреляция означает отсутствие линейной связи.</p>","choices":["Положительная корреляция отражает однонаправленную линейную связь, отрицательная — разнонаправленную.","Положительная корреляция означает, что при росте одной величины другая обычно падает.","Отрицательная корреляция означает отсутствие линейной связи."]},
  {"survey":2,"number":18,"topic":"Анализ данных и систем","prompt":"Что такое невязка?","answer":"<p>Невязка показывает, насколько приближённое решение нарушает исходное уравнение. Например, для <img class=\"formula-image\" src=\"./formulas/5de9f5494396c4c6.png\" alt=\"Ax=b\" style=\"width:3.257em;vertical-align:-0.125em\"> невязка приближения <img class=\"formula-image\" src=\"./formulas/8287a5688dbc3aba.png\" alt=\"\\tilde x\" style=\"width:0.962em;vertical-align:-0.125em\"> равна <img class=\"formula-image\" src=\"./formulas/bc6a1fdbe4e54326.png\" alt=\"r=b-A\\tilde x\" style=\"width:5.104em;vertical-align:-0.125em\">. В регрессии аналогичная величина называется остатком: <img class=\"formula-image\" src=\"./formulas/aece80899ed542b5.png\" alt=\"e_i=y_i-\\hat y_i\" style=\"width:5.232em;vertical-align:-0.490em\">.</p>","choices":["Невязка показывает отклонение от исходного уравнения при подстановке приближения, например <img class=\"formula-image\" src=\"./formulas/bc6a1fdbe4e54326.png\" alt=\"r=b-A\\tilde x\" style=\"width:5.104em;vertical-align:-0.125em\">.","Невязка всегда равна разности между точным и приближённым решениями.","Невязка — разность между двумя соседними приближениями независимо от уравнения."]},
  {"survey":2,"number":19,"topic":"Вероятность и метод Монте-Карло","prompt":"Что такое метод Монте-Карло? Для чего он используется?","answer":"<p>Это методы приближённого решения задач с помощью случайных испытаний. Их применяют для оценки вероятностей, интегралов, средних и других характеристик сложных систем. Например, математическое ожидание <img class=\"formula-image\" src=\"./formulas/db74b1ffe2a418c5.png\" alt=\"E[f(X)]\" style=\"width:3.602em;vertical-align:-0.333em\"> оценивают средним <img class=\"formula-image\" src=\"./formulas/0dea6c9d0f8c7e1e.png\" alt=\"\\tfrac1N\\sum_{i=1}^N f(X_i)\" style=\"width:5.900em;vertical-align:-0.628em\"> по независимым реализациям <img class=\"formula-image\" src=\"./formulas/2c40f725e01fb867.png\" alt=\"X_i\" style=\"width:1.186em;vertical-align:-0.329em\">.</p>","choices":["Метод Монте-Карло использует случайные испытания для оценки вероятностей, интегралов и других характеристик.","Метод Монте-Карло вычисляет точный результат, перебирая все точки непрерывной области.","Метод Монте-Карло находит производную, используя только два фиксированных значения функции."]},
  {"survey":2,"number":20,"topic":"Вероятность и метод Монте-Карло","prompt":"Что такое случайная величина?","answer":"<p>Случайная величина — числовая функция, которая каждому исходу случайного эксперимента ставит в соответствие число. Например, она может обозначать количество орлов в трёх подбрасываниях монеты.</p>","choices":["Это числовая функция, ставящая в соответствие число каждому исходу случайного эксперимента.","Это вероятность единственного выбранного исхода.","Это конкретное измеренное число, одинаковое для всех исходов эксперимента."]},
  {"survey":2,"number":21,"topic":"Вероятность и метод Монте-Карло","prompt":"Что такое случайное число?","answer":"<p>Случайное число — конкретное числовое значение, полученное при случайном испытании по заданному распределению. Например, <img class=\"formula-image\" src=\"./formulas/1db39e7cb30c8345.png\" alt=\"4\" style=\"width:0.804em;vertical-align:-0.125em\"> может быть одним результатом броска кубика. При моделировании обычно используют псевдослучайные числа, которые генерирует детерминированный алгоритм.</p>","choices":["Это конкретное числовое значение, полученное при случайном испытании по заданному распределению.","Это функция, которая описывает все возможные исходы и однозначно определяет их вероятности.","Это среднее значение всех возможных результатов испытания."]},
  {"survey":2,"number":22,"topic":"Вероятность и метод Монте-Карло","prompt":"Что такое выборка?","answer":"<p>Выборка — набор наблюдений <img class=\"formula-image\" src=\"./formulas/c1e498f0e6a6d83f.png\" alt=\"x_1,\\ldots,x_N\" style=\"width:4.406em;vertical-align:-0.329em\">, полученных из изучаемой совокупности. В классической модели простой случайной выборки наблюдения рассматривают как реализации независимых одинаково распределённых случайных величин. <img class=\"formula-image\" src=\"./formulas/cced4458f99d8984.png\" alt=\"N\" style=\"width:0.982em;vertical-align:-0.125em\"> — объём выборки.</p>","choices":["Выборка — набор наблюдений из изучаемой совокупности.","Выборка — формула для вычисления вероятности каждого исхода.","Выборка — числовое среднее всех наблюдений от одного эксперимента."]},
  {"survey":2,"number":23,"topic":"Вероятность и метод Монте-Карло","prompt":"Что такое математическое ожидание?","answer":"<p>Математическое ожидание <img class=\"formula-image\" src=\"./formulas/bc93b55068769659.png\" alt=\"E[X]\" style=\"width:2.221em;vertical-align:-0.333em\"> — среднее значение случайной величины по её распределению. Для дискретной величины <img class=\"formula-image\" src=\"./formulas/e1352d2f5f7f6d59.png\" alt=\"E[X]=\\sum_i x_iP(X=x_i)\" style=\"width:9.902em;vertical-align:-0.490em\">. Для непрерывной величины с плотностью <img class=\"formula-image\" src=\"./formulas/65502b9aa46aa325.png\" alt=\"p(x)\" style=\"width:2.171em;vertical-align:-0.333em\"> имеем <img class=\"formula-image\" src=\"./formulas/0d906b53642330ce.png\" alt=\"E[X]=\\int_{-\\infty}^{\\infty}x p(x)\\,dx\" style=\"width:9.383em;vertical-align:-0.490em\">, если ожидание существует.</p>","choices":["Это среднее значение случайной величины по её распределению, например сумма значений с весами-вероятностями в дискретном случае.","Это наиболее вероятное значение, независимо от остальных значений.","Это среднее крайних значений, независимо от распределения."]},
  {"survey":2,"number":24,"topic":"Вероятность и метод Монте-Карло","prompt":"Как погрешность метода Монте-Карло зависит от числа испытаний <img class=\"formula-image\" src=\"./formulas/cced4458f99d8984.png\" alt=\"N\" style=\"width:0.982em;vertical-align:-0.125em\">?","answer":"<p>Для среднего по <img class=\"formula-image\" src=\"./formulas/cced4458f99d8984.png\" alt=\"N\" style=\"width:0.982em;vertical-align:-0.125em\"> независимым одинаково распределённым испытаниям с конечной дисперсией <img class=\"formula-image\" src=\"./formulas/203657c1df1428a4.png\" alt=\"\\sigma^2\" style=\"width:1.293em;vertical-align:-0.125em\"> стандартная ошибка равна <img class=\"formula-image\" src=\"./formulas/7a0fd35f3deb3919.png\" alt=\"\\sigma/\\sqrt N\" style=\"width:2.826em;vertical-align:-0.333em\">. Характерный размер статистической погрешности убывает как <img class=\"formula-image\" src=\"./formulas/60bc4364eeb342b5.png\" alt=\"N^{-1/2}\" style=\"width:2.773em;vertical-align:-0.125em\">. Чтобы уменьшить его вдвое, нужно увеличить число испытаний в четыре раза.</p>","choices":["Для независимых одинаково распределённых испытаний с конечной дисперсией стандартная ошибка убывает как <img class=\"formula-image\" src=\"./formulas/433ba8ab8a3700a5.png\" alt=\"\\frac{1}{\\sqrt N}\" style=\"width:1.458em;vertical-align:-0.772em\">.","Стандартная ошибка убывает как <img class=\"formula-image\" src=\"./formulas/3aa8c751253da394.png\" alt=\"\\frac{1}{N}\" style=\"width:0.875em;vertical-align:-0.628em\">, поэтому удвоение <img class=\"formula-image\" src=\"./formulas/cced4458f99d8984.png\" alt=\"N\" style=\"width:0.982em;vertical-align:-0.125em\"> уменьшает её вдвое.","Стандартная ошибка растёт как <img class=\"formula-image\" src=\"./formulas/cb34a0ebd4ccd364.png\" alt=\"\\sqrt N\" style=\"width:1.750em;vertical-align:-0.271em\"> при увеличении числа испытаний."]},
  {"survey":2,"number":25,"topic":"Вероятность и метод Монте-Карло","prompt":"Что такое центральная предельная теорема?","answer":"<p>Если <img class=\"formula-image\" src=\"./formulas/3b6beaef939c95b0.png\" alt=\"X_1,\\ldots,X_N\" style=\"width:4.631em;vertical-align:-0.329em\"> независимы, одинаково распределены и имеют математическое ожидание <img class=\"formula-image\" src=\"./formulas/d9446f6637fb5b82.png\" alt=\"\\mu\" style=\"width:0.799em;vertical-align:-0.333em\"> и конечную положительную дисперсию <img class=\"formula-image\" src=\"./formulas/203657c1df1428a4.png\" alt=\"\\sigma^2\" style=\"width:1.293em;vertical-align:-0.125em\">, то при <img class=\"formula-image\" src=\"./formulas/776ded72c155ce70.png\" alt=\"N\\to\\infty\" style=\"width:3.226em;vertical-align:-0.125em\"> величина <img class=\"formula-image\" src=\"./formulas/315754d6cb01c204.png\" alt=\"\\sqrt N(\\overline X_N-\\mu)/\\sigma\" style=\"width:6.624em;vertical-align:-0.333em\"> сходится по распределению к стандартному нормальному закону <img class=\"formula-image\" src=\"./formulas/fc7d59b271eba432.png\" alt=\"\\mathcal N(0,1)\" style=\"width:3.293em;vertical-align:-0.333em\">. Поэтому при большом <img class=\"formula-image\" src=\"./formulas/cced4458f99d8984.png\" alt=\"N\" style=\"width:0.982em;vertical-align:-0.125em\"> выборочное среднее имеет приближённо нормальное распределение с центром <img class=\"formula-image\" src=\"./formulas/d9446f6637fb5b82.png\" alt=\"\\mu\" style=\"width:0.799em;vertical-align:-0.333em\"> и стандартным отклонением <img class=\"formula-image\" src=\"./formulas/7a0fd35f3deb3919.png\" alt=\"\\sigma/\\sqrt N\" style=\"width:2.826em;vertical-align:-0.333em\">.</p>","choices":["При стандартных условиях центрированное и нормированное выборочное среднее сходится по распределению к нормальному закону.","При увеличении выборки распределение каждого отдельного наблюдения обязательно становится нормальным.","При стандартных условиях среднее становится равномерно распределённым на всей числовой оси."]},
  {"survey":2,"number":26,"topic":"Методы оптимизации","prompt":"Что такое метод перебора? Метод деления шага пополам. Метод градиента?","answer":"<ul><li><strong>Метод перебора.</strong> Вычисляют целевую функцию для всех допустимых вариантов в конечном наборе и выбирают лучший. Для непрерывной области можно перебирать точки сетки, получая приближённое решение.</li><li><strong>Метод деления шага пополам.</strong> При поиске минимума пробуют шаг в выбранном направлении. Если пробный шаг не уменьшает целевую функцию, заменяют <img class=\"formula-image\" src=\"./formulas/790a905ad217c0a0.png\" alt=\"h\" style=\"width:0.805em;vertical-align:-0.125em\"> на <img class=\"formula-image\" src=\"./formulas/e17fcc249e1bb86c.png\" alt=\"h/2\" style=\"width:1.849em;vertical-align:-0.333em\"> и пробуют снова. При необходимости повторяют уменьшение до улучшения или до достижения заданного минимального шага.</li><li><strong>Метод градиента.</strong> Для минимизации дифференцируемой функции в методе градиентного спуска движутся против градиента: <img class=\"formula-image\" src=\"./formulas/28635e90aa880152.png\" alt=\"x_{k+1}=x_k-h_k\\nabla f(x_k)\" style=\"width:9.995em;vertical-align:-0.333em\">, где <img class=\"formula-image\" src=\"./formulas/856e5a47999f6e73.png\" alt=\"h_k&gt;0\" style=\"width:3.120em;vertical-align:-0.329em\"> — коэффициент, задающий размер шага. Для максимизации используют направление градиента.</li></ul>","choices":["Перебор оценивает варианты по очереди, деление шага уменьшает неудачный шаг вдвое, а градиентный спуск движется против градиента.","Перебор проверяет только одну точку, деление шага удваивает шаг, а градиентный спуск всегда идёт по градиенту.","Перебор и градиентный спуск выполняют только случайные шаги, а деление шага применяется только к первому варианту."]}
];
